<div class="card mb-3"><div class="card-header"><h2 class="card-title">Catat peminjaman</h2></div><form method="post" class="card-body"><input type="hidden" name="network_csrf" value="<?= html_escape($csrf); ?>"><div class="row g-3"><div class="col-md-5"><label class="form-label">Nomor anggota lokal</label><input class="form-control" name="member_no" required maxlength="120" autocomplete="off"></div><div class="col-md-5"><label class="form-label">Barcode eksemplar</label><input class="form-control" name="barcode" required maxlength="120" autocomplete="off"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Pinjamkan</button></div></div><p class="network-muted mt-2 mb-0">Jatuh tempo otomatis <?= (int)$settings['loan_days']; ?> hari. Maksimal <?= (int)$settings['max_loans']; ?> pinjaman aktif per anggota. Barcode dan anggota harus berasal dari perpustakaan ini.</p></form></div>
<div class="card"><div class="card-header"><h2 class="card-title">Transaksi peminjaman</h2><form method="get" class="d-flex gap-2"><input type="hidden" name="library_id" value="<?= (int)$scope; ?>"><select class="form-select" name="state"><?php foreach(['active'=>'Aktif','overdue'=>'Terlambat','returned'=>'Dikembalikan','all'=>'Semua']as$key=>$label): ?><option value="<?= $key; ?>" <?= $state===$key?'selected':''; ?>><?= $label; ?></option><?php endforeach; ?></select><button class="btn">Filter</button></form><div class="network-actions ms-auto"><?php foreach(['csv'=>'CSV','xlsx'=>'Excel']as$ext=>$label): ?><a class="btn network-export-<?= $ext; ?>" href="<?= html_escape($network_url('export/loans/'.$ext).'&state='.$state); ?>"><i class="ti ti-download me-1"></i><?= $label; ?></a><?php endforeach; ?></div></div>
<div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>Transaksi</th><th>Anggota</th><th>Buku</th><th>Jatuh tempo</th><th>Kembali</th><th>Aksi</th></tr></thead><tbody><?php foreach($result['rows']as$loan): ?><tr><td>#<?= (int)$loan['id']; ?><div class="small text-secondary"><?= html_escape($loan['loaned_at']); ?></div></td><td><?= html_escape($loan['full_name']); ?><div class="small"><?= html_escape($loan['member_no']); ?></div></td><td><?= html_escape($loan['title']); ?><div class="small"><?= html_escape($loan['barcode']); ?></div></td><td><?= html_escape($loan['due_at']); ?><div class="small text-secondary"><?= (int)$loan['renewal_count']; ?> perpanjangan</div></td><td><?= html_escape($loan['returned_at']?:'Belum kembali'); ?></td><td><?php if(!$loan['returned_at']): ?><div class="network-actions"><?php foreach(['return'=>'Kembalikan','renew'=>'Perpanjang']as$action=>$label): ?><form method="post" action="<?= html_escape($network_url('loan-action/'.$loan['id'].'/'.$action)); ?>" onsubmit="return confirm('Lanjutkan tindakan pada transaksi ini?');"><input type="hidden" name="network_csrf" value="<?= html_escape($csrf); ?>"><button class="btn btn-sm <?= $action==='return'?'btn-primary':'btn-outline-primary'; ?>"><?= $label; ?></button></form><?php endforeach; ?></div><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$result['rows']): ?><tr><td colspan="6" class="text-center py-4">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div><div class="card-footer network-actions"><span><?= $result['total']; ?> transaksi · halaman <?= $page; ?>/<?= $pages; ?></span><?php if($page>1): ?><a class="btn btn-sm" href="<?= html_escape($network_url('loans').'&state='.$state.'&page='.($page-1)); ?>">Sebelumnya</a><?php endif; ?><?php if($page<$pages): ?><a class="btn btn-sm" href="<?= html_escape($network_url('loans').'&state='.$state.'&page='.($page+1)); ?>">Berikutnya</a><?php endif; ?></div></div>
